"""Generate explicit source/candidate pairs from immutable v09 records and locally built v10 assets."""
from pathlib import Path
import json,hashlib,sys,copy
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'scripts'));from v05.overlay import read
h=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
source=json.loads((R/'library-v09/catalog.json').read_text());entries=[]
for key in ['horse-brown','horse-white']:
 F=R/'library-v10'/(key+'-grounded-review')/'0.1.0'
 if not (F/'adaptation.json').exists():continue
 m=json.loads((F/'adaptation.json').read_text());a=copy.deepcopy(next(e for e in source['entries'] if e['asset_id']==key));b=copy.deepcopy(a);b['asset_id']=key+'-grounded-review';b['version']='0.1.0';b['id']=b['asset_id']+'@'+b['version'];b['variant']='corrected';b['name']=('棕馬' if key=='horse-brown' else '白馬')+' · 接地與循環候選';b['model']={'url':'../'+str((F/'model.glb').relative_to(R)),'sha256':m['model_sha256'],'bytes':(F/'model.glb').stat().st_size};b['editable']={'path':str((F/'model.blend').relative_to(R)),'sha256':m['mother_sha256'],'description':'Native 13-action mother; Walk/Gallop replaced, packed original textures, 50 bones'};b['modifications']=['Gallop cyclic local-TRS bridge; Walk/Gallop hoof clearance with native-length two-link solve.','11 other GLB clips, old binary, meshes, skins, materials, textures and rest definitions preserved.','No root motion or world sliding correction.'];b['warning']='接地與循環候選；原地步態，世界速度／腳滑未驗收，人工美術未測。';b['phase_ranges']={};a['phase_ranges']={};a['variant']='baseline';a['name']=('棕馬' if key=='horse-brown' else '白馬')+' · 原版 2.3.0';a['warning']='原版比較：Walk 蹄部穿地、Gallop 蹄部穿地與循環跳接尚未修正。';a['default_clip']=b['default_clip']='Gallop';a['pair_baseline']=b['pair_baseline']=a['id'];a['pair_corrected']=b['pair_corrected']=b['id'];audit=json.loads((F/'motion-audit.json').read_text())['clips']
 for c in b['clips']:
  if c['name'] in audit:
   old=next(x for x in a['clips'] if x['name']==c['name']);a['phase_ranges'][c['name']]=[old['first_key_s'],old['last_key_s']];c.update(duration_s=audit[c['name']]['duration_s'],first_key_s=0,last_key_s=audit[c['name']]['duration_s'],key_span_s=audit[c['name']]['duration_s']);b['phase_ranges'][c['name']]=[0,c['duration_s']]
 profile=json.loads((R/a['profile'].removeprefix('../')).read_text());profile.update(asset_id=b['asset_id'],version=b['version'],model_sha256=m['model_sha256'],clips=b['clips'],adaptation=m,source_profile=a['profile']);(F/'skeleton-profile.json').write_text(json.dumps(profile,indent=2)+'\n');b['profile']='../'+str((F/'skeleton-profile.json').relative_to(R));b['profile_sha256']=h(F/'skeleton-profile.json');entries.extend([a,b])
 manifest={'schema_version':1,'asset_id':b['asset_id'],'format':'glTF 2.0 GLB','source':'Quaternius CC0 / aitest-ai Horse Library 2.3.0; native bone motion correction','unit':'source native; explicit display_calibration supplied; not biological size certification','coordinate_system':'Blender Z-up / glTF Y-up, forward -Y / +Z','model_file':'model.glb','source_file':'model.blend','clips':[c['name'] for c in b['clips']],'min_animation_count':13,'requirements':{'skins':True,'animated':True,'visual_review':True},'license_note':'CC0 source and retained procedural UV/PBR/mane; see THIRD_PARTY_V10.md'};(F/'asset_manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');(F/'report.json').write_text(json.dumps({'status':'candidate','art_approved':False,'game_ready':False,'source_sha256':m['source_glb_sha256'],'model_sha256':m['model_sha256'],'changes':b['modifications'],'known_limitations':['in-place only; no calibrated world sliding test','no turns, starts/stops or gameplay integration','physical mobile and human art untested']},indent=2)+'\n')
(R/'library-v10/catalog.json').write_text(json.dumps({'version':'0.10.0','entries':entries},indent=2)+'\n');print('CATALOG',len(entries))
